class Statement{
 constructor(sql,args=[]){this.sql=sql;this.args=args;}
 bind(...args){return new Statement(this.sql,args);}
 async first(){return sqlite.prepare(this.sql).get(...this.args)??null;}
 async all(){return {results:sqlite.prepare(this.sql).all(...this.args)};}
 async run(){return sqlite.prepare(this.sql).run(...this.args);}
}
const db={prepare:sql=>new Statement(sql),async batch(list){sqlite.exec('BEGIN');try{const r=[];for(const s of list)r.push(await s.run());sqlite.exec('COMMIT');return r;}catch(e){sqlite.exec('ROLLBACK');throw e;}},async withReadSnapshot(read){sqlite.exec('BEGIN');try{return await read(this);}finally{sqlite.exec('ROLLBACK');}}};
const sessions={};
async function call(who,path,method='GET',data,headers={},extra={}){
 const local=typeof who==='string'&&who.startsWith('local:'),identity=who&&!local?{userId:who,email:who==='owner'?'owner@example.test':who+'@example.test'}:null,current=sessions[who]??{};
 const req=new Request('https://portal.example.test'+path,{method,headers:{'content-type':'application/json','origin':'https://portal.example.test','x-csrf-token':current.csrf??'',...(current.cookie?{cookie:current.cookie}:{}),...headers},...(data===undefined?{}:{body:JSON.stringify(data)})});
 const r=await handle(req,{db,identity,ownerEmail:'owner@example.test',newDepositsEnabled:'true',newGameLaunchesEnabled:'true',...extra}),setCookie=r.headers.get('set-cookie'),response={status:r.status,data:await r.json()};
 if(who&&setCookie)sessions[who]={...current,cookie:setCookie.split(';')[0]};if(who&&path==='/api/session')sessions[who]={...(sessions[who]??current),csrf:response.data.csrf};return response;
}
